import subprocess, tempfile, os, glob
def run(args, stdin_data=""):
    p=subprocess.run(["./executable"]+args, input=stdin_data, capture_output=True, text=True)
    return p.stdout, p.stderr, p.returncode
def mk(suffix, content):
    f=tempfile.NamedTemporaryFile(mode='w', suffix=suffix, delete=False)
    f.write(content); f.close()
    return f.name
def clean():
    for fp in glob.glob("/tmp/dsq-cache*"):
        try: os.unlink(fp)
        except: pass

f=mk('.csv',"a,b\n1,2\n")
for args in [["-C",f],["-D",f],["-D","-C",f],["-D",f,"SELECT * FROM {}"],["-D",f,"--schema"]]:
    clean()
    o,e,rc=run(args)
    files=glob.glob("/tmp/dsq-cache*")
    print(f"ARGS={args} rc={rc} out={repr(o[:500])} err={repr(e[:500])} files={files}")
os.unlink(f)
