# Helper to test our go number formatting
import math, re
def format_go_number(v):
    if isinstance(v, bool):
        return 'true' if v else 'false'
    if isinstance(v, int) and not isinstance(v, bool):
        return str(v)
    if isinstance(v, float):
        if math.isnan(v) or math.isinf(v):
            return 'null'
        if v == 0.0:
            import math as m
            if m.copysign(1, v) < 0:
                return '-0'
            else:
                return '0'
        av = abs(v)
        if av < 1e-6 or av >= 1e21:
            s = repr(v)
            if 'e' in s or 'E' in s:
                m = re.match(r'^(.*)[eE]([+-]?)0*(\d+)$', s)
                if m:
                    mant, sign, exp = m.groups()
                    exp = exp.lstrip('0')
                    if exp == '':
                        exp = '0'
                    # reconstruct: mant + 'e' + sign + exp ; if sign empty, need '+'? Python always has sign, so keep
                    s = f"{mant}e{sign}{exp}"
            return s
        else:
            if v.is_integer():
                try:
                    return str(int(v))
                except:
                    pass
            s_repr = repr(v)
            if 'e' not in s_repr and 'E' not in s_repr:
                if '.' in s_repr:
                    s_repr = s_repr.rstrip('0').rstrip('.')
                return s_repr
            else:
                from decimal import Decimal
                d = Decimal(str(v))
                s = format(d, 'f')
                if '.' in s:
                    s = s.rstrip('0').rstrip('.')
                return s
    return str(v)

tests=[(1.0,'1'),(1.00,'1'),(0.0,'0'),(-0.0,'-0'),(2.5,'2.5'),(1e10,'10000000000'),(1e20,'100000000000000000000'),(1e21,'1e+21'),(1e22,'1e+22'),(1e-6,'0.000001'),(1e-7,'1e-7'),(0.000001,'0.000001'),(0.0000001,'1e-7'),(1.5e-7,'1.5e-7'),(1.234e21,'1.234e+21'),(0.3333333333333333,'0.3333333333333333')]
